/**
 * Orchestrator Playground: natural-language request -> structured execution plan.
 *
 * A plan is generated by the environment's text generation model, constrained to
 * the fixed agent role registry, then statically validated (roles, references,
 * cycles) before it reaches the client. Simulation, replay and live execution
 * are separate layers built on this contract.
 */
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";

import { AgentRoleIdSchema } from "./agentRoles.ts";
import { ProjectId, TrimmedNonEmptyString } from "./baseSchemas.ts";
import { ModelSelection } from "./modelSelection.ts";

export const OrchestrationPlanStepId = TrimmedNonEmptyString.check(Schema.isMaxLength(64));
export type OrchestrationPlanStepId = typeof OrchestrationPlanStepId.Type;

export const OrchestrationPlanStepTask = TrimmedNonEmptyString.check(Schema.isMaxLength(2_000));
export type OrchestrationPlanStepTask = typeof OrchestrationPlanStepTask.Type;

/**
 * One step in a generated plan. `roleId` is constrained to the fixed agent role
 * registry on the wire; an unknown role fails decode rather than silently
 * reaching execution. `dependsOn` names sibling step ids; approval gates are
 * explicit and cannot be cleared by the planner.
 */
export const OrchestrationPlanStep = Schema.Struct({
  id: OrchestrationPlanStepId,
  roleId: AgentRoleIdSchema,
  task: OrchestrationPlanStepTask,
  dependsOn: Schema.Array(OrchestrationPlanStepId).pipe(
    Schema.withDecodingDefaultKey(Effect.succeed([])),
  ),
  requiresApproval: Schema.Boolean.pipe(Schema.withDecodingDefaultKey(Effect.succeed(false))),
});
export type OrchestrationPlanStep = typeof OrchestrationPlanStep.Type;

export const OrchestrationPlanSummary = TrimmedNonEmptyString.check(Schema.isMaxLength(1_000));
export type OrchestrationPlanSummary = typeof OrchestrationPlanSummary.Type;

export const OrchestrationPlan = Schema.Struct({
  summary: OrchestrationPlanSummary,
  steps: Schema.Array(OrchestrationPlanStep).pipe(
    Schema.withDecodingDefaultKey(Effect.succeed([])),
  ),
});
export type OrchestrationPlan = typeof OrchestrationPlan.Type;

export const OrchestrationPlanDiagnosticSeverity = Schema.Literals(["error", "warning"]);
export type OrchestrationPlanDiagnosticSeverity = typeof OrchestrationPlanDiagnosticSeverity.Type;

export const OrchestrationPlanDiagnosticCode = Schema.Literals([
  "empty-plan",
  "duplicate-step-id",
  "unknown-role",
  "missing-dependency",
  "self-dependency",
  "cycle",
]);
export type OrchestrationPlanDiagnosticCode = typeof OrchestrationPlanDiagnosticCode.Type;

export const OrchestrationPlanDiagnostic = Schema.Struct({
  severity: OrchestrationPlanDiagnosticSeverity,
  code: OrchestrationPlanDiagnosticCode,
  message: Schema.String,
  stepId: Schema.optionalKey(Schema.String),
});
export type OrchestrationPlanDiagnostic = typeof OrchestrationPlanDiagnostic.Type;

/**
 * Static validation of a plan. `executionOrder` carries a deterministic
 * topological order and is only populated when the plan has no error-severity
 * diagnostics. Diagnostics are empty for a valid plan.
 */
export const OrchestrationPlanValidation = Schema.Struct({
  valid: Schema.Boolean,
  diagnostics: Schema.Array(OrchestrationPlanDiagnostic).pipe(
    Schema.withDecodingDefaultKey(Effect.succeed([])),
  ),
  executionOrder: Schema.Array(OrchestrationPlanStepId).pipe(
    Schema.withDecodingDefaultKey(Effect.succeed([])),
  ),
});
export type OrchestrationPlanValidation = typeof OrchestrationPlanValidation.Type;

export const OrchestrationPlaygroundPrompt = TrimmedNonEmptyString.check(
  Schema.isMaxLength(16_000),
);

export const GenerateOrchestrationPlanInput = Schema.Struct({
  prompt: OrchestrationPlaygroundPrompt,
  modelSelection: Schema.optionalKey(ModelSelection),
  projectId: Schema.optionalKey(ProjectId),
});
export type GenerateOrchestrationPlanInput = typeof GenerateOrchestrationPlanInput.Type;

export const GenerateOrchestrationPlanResult = Schema.Struct({
  plan: OrchestrationPlan,
  validation: OrchestrationPlanValidation,
  /** The selection the plan was generated with (the fallback when none was requested). */
  modelSelection: ModelSelection,
});
export type GenerateOrchestrationPlanResult = typeof GenerateOrchestrationPlanResult.Type;

export class OrchestratorPlaygroundError extends Schema.TaggedError<OrchestratorPlaygroundError>()(
  "OrchestratorPlaygroundError",
  {
    message: TrimmedNonEmptyString,
    cause: Schema.optional(Schema.Defect()),
  },
) {}
